schema:
model RAJob (server/prisma/schema/ra-jobs.prisma), one new block directly above the relation line "userStates RAJobUserState[]", all additive:
  // ── Market wave (MKT-0; MARKET_STRATEGY 2.3 and 7 item 11). Additive. ──
  /// K2 exact dedupe key '{ats}:{tenant}:{postingId}' parsed from the apply or source URL. JI-5.
  atsPostingKey     String?
  /// Who states RAJob.sponsorship: 'posting_quote' | 'provider:<provider id>' (a provider's reading, labelled as such). JI-7, JI-11.
  sponsorshipSource String?
  /// Taiwan 鄉鎮市區 as posted, e.g. '竹北市'. JT-7.
  locationDistrict  String?
  /// 'day' | 'evening' | 'night' | 'rotating' | 'part_time' from the source's own field; null = not stated. JT-7.
  workShift         String?
  /// Score 0..1 of the deterministic title-to-role match (taxonomy/match.ts) that produced primaryTaxonomyId; null = never matched. SM-2.
  titleMatchScore   Float?   @db.Real
  /// Canonical RASkill ids of the posting's skills, required first. SM-6.
  skillIds          String[] @default([])
  /// Lexical document (title, role labels en/zh/zhHant, canonical skill labels and aliases, summary, requirements head). CJK segmented in the application; Traditional folded to Simplified in this token copy only. Never displayed. SM-7.
  searchDoc         String?  @db.Text
  /// to_tsvector('simple', searchDoc), written by the application in the same statement as searchDoc. NOT a generated column (prisma db push cannot express one). SM-7.
  searchTsv         Unsupported("tsvector")?
  /// sha1 of the content a fit depends on: title + requirements text + skills. SM-5, SM-7.
  contentHash       String?
  /// Language of the posting text: 'en' | 'zh-Hans' | 'zh-Hant' | 'ja' | 'ko' | other BCP-47 primary tag. SM-7, SM-11.
  lang              String?
  /// { v: 1, contentHash, model, extractedAt, items: [{ id, kind: 'skill'|'experience'|'education'|'domain'|'scope', text (verbatim from the posting), importance: 'must'|'preferred' }] }. SM-8.
  requirements      Json?
  embedding         RAJobEmbedding?
and after the last existing @@index of the model:
  @@index([market, atsPostingKey])
  @@index([market, locationCountry, locationDistrict])
  @@index([skillIds], type: Gin)
  @@index([searchTsv], type: Gin)   // only if prisma validate refuses the plain form: @@index([searchTsv(ops: raw("tsvector_ops"))], type: Gin), then record the pair in schema-diffs/KNOWN_DRIFT.md

model RACareerSiteSource (server/prisma/schema/ra-jobs.prisma), after lastError, all additive:
  /// 'admin' | 'seed' | 'import' | 'discovered'. JI-3.
  origin         String    @default("admin")
  /// For origin 'discovered': '<sourceBoard>:<externalId>' of the row that named the board, or 'user_import'. JI-3.
  discoveredFrom String?
  /// ISO alpha-2 codes the board is read for; empty = every country the brands serve. JI-3, JC-4, JT-5.
  countries      String[]  @default([])
  /// Consecutive hard sync failures; 3 disables the source. JI-4.
  failCount      Int       @default(0)
  /// When a sync last added or closed a posting (adaptive interval). JI-4.
  lastChangeAt   DateTime?
  /// When the board is next due; null = now; also the sync lease. JI-4.
  nextSyncAt     DateTime?
  /// Set when three failures disabled the source; its rows are archived 48 h later. JI-4.
  disabledAt     DateTime?
and in the index list:
  @@index([enabled, nextSyncAt])

model RAJobMatchScore (server/prisma/schema/ra-match.prisma), additive:
  /// RAJob content hash (title + requirements + skills) at score time; a changed posting makes the row stale. SM-5.
  jobContentHash String?
  /// 'fit_v3' | 'fit_v4': the rubric the stored components follow. SM-5, SM-8.
  rubricVersion  String?

model RAUserAffinity (server/prisma/schema/ra-feed.prisma), additive:
  /// { normalizedTitleKey: -1..0 } negative weights from "Not interested: wrong title". SM-12.
  titleWeights Json @default("{}")

model RATailorSession (server/prisma/schema/ra-resume.prisma), additive:
  /// { before: FitSnapshot | null, after: FitSnapshot | null } with FitSnapshot = { score, tier, kind, rubric, estimator, model, scoredAt } (strategy 2.2 I6). SM-5.
  fitSnapshot Json?
